INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (440, 1, 'Create 모드', 'mdadm 의 **Create** 모드는 무엇을 할까요?', '새 배열이에요.', NULL, NULL, '[]', 'choice', '["이미 만든 배열을 다시 활성화한다", "superblock 없이 배열을 만든다", "superblock 을 기록하는 새 배열을 만든다", "배열의 상태 변화를 감시한다"]', 2, 'mdadm 문서는 Create 가 장치별 메타데이터(superblock)를 가진 새 배열을 만든다고 설명합니다.', NULL, NULL, NULL, '[{"title": "mdadm(8) man page", "url": "https://man7.org/linux/man-pages/man8/mdadm.8.html"}]'),
  (440, 2, 'Build 모드', 'mdadm 의 **Build** 모드는 Create 와 무엇이 다를까요?', '메타데이터 유무예요.', NULL, NULL, '[]', 'choice', '["배열의 크기를 새로 바꾼다", "장치별 superblock 이 없다", "여유 장치만 따로 추가한다", "여러 배열을 컨테이너로 묶는다"]', 1, '문서는 Build 가 장치별 메타데이터(superblock)가 없는 배열을 만든다고 설명합니다.', NULL, NULL, NULL, '[{"title": "mdadm(8) man page", "url": "https://man7.org/linux/man-pages/man8/mdadm.8.html"}]'),
  (440, 3, 'Assemble 모드', 'mdadm 의 **Assemble** 모드는 무엇을 할까요?', '다시 조립해요.', NULL, NULL, '[]', 'choice', '["이전에 만든 배열을 활성 배열로 조립한다", "새 배열을 만들고 초기화한다", "배열의 RAID 수준을 다른 것으로 바꾼다", "장애가 난 장치를 목록에서 지운다"]', 0, '문서는 Assemble 이 이전에 만든 배열의 구성 요소를 활성 배열로 조립한다고 설명합니다.', NULL, NULL, NULL, '[{"title": "mdadm(8) man page", "url": "https://man7.org/linux/man-pages/man8/mdadm.8.html"}]'),
  (440, 4, 'Manage 모드', 'mdadm 의 **Manage** 모드는 무엇을 위한 모드일까요?', '구성 요소 단위예요.', NULL, NULL, '[]', 'choice', '["배열 전체를 감시한다", "배열을 새로 만든다", "배열의 크기를 줄인다", "특정 구성 요소를 다룬다"]', 3, '문서는 Manage 가 배열의 특정 구성 요소를 다루는 모드이며 여유 장치 추가나 장애 장치 제거 같은 일을 한다고 설명합니다.', NULL, NULL, NULL, '[{"title": "mdadm(8) man page", "url": "https://man7.org/linux/man-pages/man8/mdadm.8.html"}]'),
  (440, 5, 'Grow 모드', 'mdadm 의 **Grow** 모드는 무엇을 할까요?', '키우거나 바꿔요.', NULL, NULL, '[]', 'choice', '["배열의 superblock 을 지운다", "배열의 상태를 감시한다", "크기나 모양을 바꾼다", "배열을 자동으로 조립한다"]', 2, '문서는 Grow 가 배열의 크기를 바꾸거나 장치 수·RAID 수준 같은 모양을 바꾼다고 설명합니다.', NULL, NULL, NULL, '[{"title": "mdadm(8) man page", "url": "https://man7.org/linux/man-pages/man8/mdadm.8.html"}]'),
  (440, 6, 'Monitor 모드', 'mdadm 의 **Monitor**(Follow) 모드는 무엇을 할까요?', '지켜봐요.', NULL, NULL, '[]', 'choice', '["배열의 데이터를 검증한다", "상태 변화를 감시하고 대응한다", "배열을 새로 만들고 초기화한다", "배열의 chunk 크기를 바꾼다"]', 1, '문서는 Monitor 가 하나 이상의 md 장치를 감시하며 상태 변화에 대응한다고 설명합니다.', NULL, NULL, NULL, '[{"title": "mdadm(8) man page", "url": "https://man7.org/linux/man-pages/man8/mdadm.8.html"}]'),
  (440, 7, 'chunk 기본값', '`--create` 에서 `--chunk` 의 **기본값** 은 얼마일까요?', 'KB 단위예요.', NULL, NULL, '[]', 'choice', '["512KB", "64KB", "4KB", "1MB"]', 0, '문서는 --chunk 가 KB 단위 chunk 크기이며 create 의 기본값이 512KB 라고 설명합니다.', NULL, NULL, NULL, '[{"title": "mdadm(8) man page", "url": "https://man7.org/linux/man-pages/man8/mdadm.8.html"}]'),
  (440, 8, 'linear 수준', 'RAID 수준 `linear` 는 무엇일까요?', '이어 붙여요.', NULL, NULL, '[]', 'choice', '["장치들을 서로 미러링한다", "패리티로 장애를 견딘다", "하나의 장치에 오류를 주입한다", "이어 붙여 큰 장치 하나로 만든다"]', 3, '문서는 linear 가 여러 장치를 이어 붙여 하나의 큰 장치로 만든다고 설명합니다. raid0 은 스트라이핑, raid1 은 미러링입니다.', NULL, NULL, NULL, '[{"title": "mdadm(8) man page", "url": "https://man7.org/linux/man-pages/man8/mdadm.8.html"}]'),
  (440, 9, 'multipath', 'RAID 수준 `multipath` 에 대해 문서는 무엇이라 할까요?', '폐기 예정이에요.', NULL, NULL, '[]', 'choice', '["문서가 가장 권장하는 수준이다", "raid10 과 같은 의미의 수준이다", "폐기되었고 multipath-tools 를 권한다", "컨테이너를 만드는 데 쓰는 수준이다"]', 2, '문서는 multipath 가 폐기되었고 각 장치가 하나의 공유 물리 장치로 가는 경로이며, 새 설치는 multipath-tools 를 쓰라고 설명합니다.', NULL, NULL, NULL, '[{"title": "mdadm(8) man page", "url": "https://man7.org/linux/man-pages/man8/mdadm.8.html"}]'),
  (440, 10, 'RAID 수준', '배열의 **RAID 수준** 을 정하는 옵션입니다. 빈칸을 채우세요.', 'level 이에요.', NULL, NULL, '[]', 'fill', '["--level", "--chunk", "--bitmap", "--metadata"]', NULL, '--level(-l)은 RAID 수준을 정합니다. --chunk 는 chunk 크기, --bitmap 은 write-intent 비트맵입니다.', '[0]', 'mdadm --create /dev/md0 {0}=1 --raid-devices=2 /dev/sda /dev/sdb', NULL, '[{"title": "mdadm(8) man page", "url": "https://man7.org/linux/man-pages/man8/mdadm.8.html"}]'),
  (440, 11, '활성 장치 수', '배열의 **활성 장치 수** 를 정하는 옵션입니다. 빈칸을 채우세요.', '"raid" 의 장치 수예요.', NULL, NULL, '[]', 'fill', '["--raid-devices", "--spare-devices", "--chunk", "--level"]', NULL, '--raid-devices(-n)는 배열의 활성 장치 수, --spare-devices(-x)는 초기 여유 장치 수입니다.', '[0]', 'mdadm --create /dev/md0 --level=1 {0}=2 /dev/sda /dev/sdb', NULL, '[{"title": "mdadm(8) man page", "url": "https://man7.org/linux/man-pages/man8/mdadm.8.html"}]'),
  (440, 12, '배열 생애', '배열을 만들고 멈췄다가 다시 활성화하는 큰 줄기 순서입니다. 순서에 맞게 놓아 보세요.', '생성 → 확인 → 중지 → 조립이에요.', NULL, NULL, '[]', 'order', '["`mdadm --create` 로 superblock 이 있는 배열을 만든다", "`mdadm --detail` 로 활성 배열의 상태를 확인한다", "`mdadm --stop` 으로 배열을 비활성화한다", "`mdadm --assemble` 로 배열을 다시 활성화한다"]', NULL, '문서의 create·detail·stop·assemble 설명을 이은 일반 절차입니다.', '[0, 1, 2, 3]', NULL, NULL, '[{"title": "mdadm(8) man page", "url": "https://man7.org/linux/man-pages/man8/mdadm.8.html"}]');
